      // Test 5: UTXO and Transaction Validation
      await _testTransactionValidation(logs);
      
      // Test 6: Fee Estimation
      await _testFeeEstimation(logs);
      
      logs.add("All Bitcoin programmed tests completed successfully");
      
      return TestResult(
        success: true,
        message: "Bitcoin programmed tests completed successfully",
        logs: logs,
        executionTime: Duration.zero,
      );
      
    } catch (e, stack) {
      logs.add("Bitcoin programmed tests failed: $e");
